mapper.select:
SELECT 
FROM practice_subject s
LEFT JOIN sys_dept d ON d.dept_id = s.dept_id AND d.del_flag = '0'

    s.deleted = 0

        AND s.dept_id = #{scopeDeptId}


        AND s.dept_id = #{deptId}


        AND s.status = #{status}


        AND s.content LIKE CONCAT('%', #{content}, '%')


ORDER BY s.status DESC, s.id DESC
